CREATE DATABASE ott_media_analytics CHARACTER SET utf8mb4;
USE ott_media_analytics;
-- OTT analytics (clean, no NULLs) - portable SQL for MySQL 8+ / PostgreSQL / SQLite
-- Run the whole file: tables are created and all data is inserted.

DROP TABLE IF EXISTS platforms;
CREATE TABLE platforms (
  platform_id INTEGER NOT NULL,
  name VARCHAR(500) NOT NULL,
  PRIMARY KEY (platform_id)
);

DROP TABLE IF EXISTS metrics;
CREATE TABLE metrics (
  metric_id INTEGER NOT NULL,
  name VARCHAR(500) NOT NULL,
  std_unit VARCHAR(500) NOT NULL,
  PRIMARY KEY (metric_id)
);

DROP TABLE IF EXISTS genres;
CREATE TABLE genres (
  genre_id INTEGER NOT NULL,
  name VARCHAR(500) NOT NULL,
  PRIMARY KEY (genre_id)
);

DROP TABLE IF EXISTS platform_metrics;
CREATE TABLE platform_metrics (
  platform_id INTEGER NOT NULL,
  metric_id INTEGER NOT NULL,
  year INTEGER NOT NULL,
  value_raw DOUBLE PRECISION NOT NULL,
  raw_unit VARCHAR(500) NOT NULL,
  value_std DOUBLE PRECISION NOT NULL,
  detail VARCHAR(500) NOT NULL,
  source_file VARCHAR(500) NOT NULL,
  PRIMARY KEY (platform_id, metric_id, year, source_file)
);

DROP TABLE IF EXISTS titles;
CREATE TABLE titles (
  title_id INTEGER NOT NULL,
  platform_id INTEGER NOT NULL,
  title VARCHAR(500) NOT NULL,
  type VARCHAR(500) NOT NULL,
  release_year INTEGER NOT NULL,
  genre_id INTEGER NOT NULL,
  rating VARCHAR(500) NOT NULL,
  maturity VARCHAR(500) NOT NULL,
  country VARCHAR(500) NOT NULL,
  runtime_min INTEGER NOT NULL,
  seasons INTEGER NOT NULL,
  PRIMARY KEY (title_id)
);

DROP TABLE IF EXISTS films;
CREATE TABLE films (
  film_id INTEGER NOT NULL,
  industry VARCHAR(500) NOT NULL,
  title VARCHAR(500) NOT NULL,
  release_date DATE NOT NULL,
  year INTEGER NOT NULL,
  genre_id INTEGER NOT NULL,
  language VARCHAR(500) NOT NULL,
  revenue_usd DOUBLE PRECISION NOT NULL,
  budget_usd DOUBLE PRECISION NOT NULL,
  profit_usd DOUBLE PRECISION NOT NULL,
  roi_x DOUBLE PRECISION NOT NULL,
  score INTEGER NOT NULL,
  score_band VARCHAR(500) NOT NULL,
  country_code VARCHAR(500) NOT NULL,
  PRIMARY KEY (film_id)
);

DROP TABLE IF EXISTS netflix_region_metrics;
CREATE TABLE netflix_region_metrics (
  year INTEGER NOT NULL,
  region VARCHAR(500) NOT NULL,
  subscribers_m DOUBLE PRECISION NOT NULL,
  revenue_b DOUBLE PRECISION NOT NULL,
  arpu_per_year DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (year, region)
);

DROP TABLE IF EXISTS quarterly_revenue;
CREATE TABLE quarterly_revenue (
  period VARCHAR(500) NOT NULL,
  year INTEGER NOT NULL,
  quarter VARCHAR(500) NOT NULL,
  revenue_b DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (period)
);

DROP TABLE IF EXISTS hulu_live_tv_subscribers;
CREATE TABLE hulu_live_tv_subscribers (
  period VARCHAR(500) NOT NULL,
  subscribers_m DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (period)
);

DROP TABLE IF EXISTS china_app_usage;
CREATE TABLE china_app_usage (
  app VARCHAR(500) NOT NULL,
  usage_m DOUBLE PRECISION NOT NULL
);

DROP TABLE IF EXISTS china_app_subscribers;
CREATE TABLE china_app_subscribers (
  app VARCHAR(500) NOT NULL,
  subscribers_m DOUBLE PRECISION NOT NULL,
  paid_conversion VARCHAR(500) NOT NULL
);
